def choose_move(observation):
    def clamp_step(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def pos(x):
        if isinstance(x, (list, tuple)) and len(x) >= 2:
            return x[0], x[1]
        return None

    def step_toward(a, b):
        if a is None or b is None:
            return [0, 0]
        ax, ay = a
        bx, by = b
        return [clamp_step(bx - ax), clamp_step(by - ay)]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def best_of(items, origin):
        best_item = None
        best_score = None
        for it in items or []:
            p = pos(it)
            if p is None:
                continue
            s = manhattan(origin, p)
            if best_score is None or s < best_score:
                best_score = s
                best_item = p
        return best_item

    env = observation.get("environment_name") or observation.get("env") or "resource_collection"
    self_pos = pos(observation.get("self_position")) or (0, 0)
    opp_pos = pos(observation.get("opponent_position")) or self_pos

    if env == "pursuit_evasion":
        role = observation.get("self_role") or observation.get("role") or "pursuer"
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)
        gw = observation.get("grid_width") or 0
        gh = observation.get("grid_height") or 0
        corners = []
        if gw and gh:
            corners = [(0, 0), (0, gh - 1), (gw - 1, 0), (gw - 1, gh - 1)]
        if not corners:
            return step_toward(self_pos, (self_pos[0] + (1 if self_pos[0] <= opp_pos[0] else -1),
                                          self_pos[1] + (1 if self_pos[1] <= opp_pos[1] else -1)))
        target = corners[0]
        far = -1
        for c in corners:
            d = manhattan(c, opp_pos)
            if d > far:
                far = d
                target = c
        return step_toward(self_pos, target)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
        target = best_of(targets, self_pos)
        if target is None:
            opp_ter = observation.get("opponent_territory") or []
            target = best_of(opp_ter, self_pos)
        if target is None:
            return step_toward(self_pos, opp_pos)
        return step_toward(self_pos, target)

    resources = observation.get("resources") or observation.get("resource_cells") or observation.get("resource_positions") or []
    target = best_of(resources, self_pos)
    if target is not None:
        return step_toward(self_pos, target)

    # Fallbacks: chase nearest useful object or hold position.
    threats = observation.get("opponents") or []
    if threats:
        opp = best_of(threats, self_pos)
        if opp is not None:
            return step_toward(self_pos, opp)

    return [0, 0]

